export function HelpCentreWidget({
  heading = "{{heading}}",
  searchPlaceholder = "{{searchPlaceholder}}",
  articleCount = {{articleCount}},
  variant = "{{variant}}",
  accent = "{{accent}}",
}) {
  const wrap = {
    panel: { border: "1.5px solid #24143022", borderRadius: 12 },
    popover: { borderRadius: 12, boxShadow: "0 14px 30px rgba(36,20,48,.2)" },
    sidebar: { borderLeft: "3px solid " + accent, maxWidth: 260 },
  }[variant] ?? {};
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: "#241430", maxWidth: 300, padding: 18, background: "#FAF7F2", ...wrap }}>
      <h3 style={{ margin: "0 0 10px", fontSize: 16, fontWeight: 600 }}>{heading}</h3>
      <label style={{ display: "flex", alignItems: "center", gap: 8, border: "1.5px solid #24143030", borderRadius: 8, padding: "8px 10px", color: "#24143099" }}>
        <svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true"><circle cx="7" cy="7" r="5.2" stroke="currentColor" strokeWidth="1.4" /><path d="M11 11l3.2 3.2" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" /></svg>
        <input type="text" placeholder={searchPlaceholder} style={{ border: "none", outline: "none", fontSize: 13.5, flex: 1, background: "transparent", color: "#241430" }} />
      </label>
      <p style={{ margin: "10px 0", fontSize: 12, color: accent, fontWeight: 600 }}>{articleCount} articles available</p>
      <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: 6 }}>
        {["Getting started with your workspace", "Managing billing and seats", "Connecting integrations"].map((item) => (
          <li key={item}><a href="#" style={{ color: "#241430", textDecoration: "none", fontSize: 13.5, padding: "6px 0", display: "block", borderBottom: "1px solid #24143014" }}>{item}</a></li>
        ))}
      </ul>
    </div>
  );
}
